use strict; use warnings;
my $p = shift or die "usage\n";
open(my $fh, "<:raw", $p) or die $!; local $/; my $d = <$fh>; close $fh;
my $lo = index($d, "PK\x03\x04");
my @f = unpack("V v v v v v V V V v v", substr($d, $lo, 30));
my ($sig,$ver,$flags,$meth,$time,$date,$crc,$csz,$usz,$fnl,$exl) = @f;
my $name = substr($d, $lo+30, $fnl);
my $doff = $lo+30+$fnl+$exl;
