printf "local_off=%d name=%s method=%d csz=%d usz=%d crc=%08X data_off=%d\n", $lo, $name, $meth, $csz, $usz, $crc, $doff;
print "stored_blob_hex=", unpack("H*", $blob), "\n";
my @tab; for my $n (0..255) { my $c=$n; for (1..8) { $c = ($c & 1) ? (0xEDB88320 ^ ($c >> 1)) : ($c >> 1); } $tab[$n]=$c; }
sub crc32 { my $s=shift; my $c=0xFFFFFFFF; for my $b (unpack("C*",$s)) { $c = $tab[($c ^ $b) & 255] ^ ($c >> 8); } return $c ^ 0xFFFFFFFF; }
my $pw = "8XDP5Q2RT9ZK7VB3BV4WW54";
printf "pw_len=%d prefix=%s suffix=%s charset=%s\n", length($pw), substr($pw,0,3), substr($pw,-3), ($pw =~ /^[A-Z0-9]+$/ ? "ok" : "BAD");
my $found = 0;
for my $cand ("PASSWORD=$pw\n", "PASSWORD=$pw", "PASSWORD=$pw\r\n") {
